// src/engine/mutationRepair.ts
// Robust parser and self-healing engine for LLM-generated JSON mutation plans.
// Handles code-fences, trailing commas, unquoted keys, and partial malformed elements.

import { AIMutationPlanSchema, GraphMutationSchema } from "@/schemas/mutations";
import { AIMutationPlan, GraphMutation } from "@/types/mutations";

export interface RepairResult {
  success: boolean;
  plan: AIMutationPlan | null;
  recoveredMutationsCount: number;
  droppedMutationsCount: number;
  warnings: string[];
}

/**
 * Attempts to repair malformed JSON string generated by LLMs.
 */
function sanitizeJsonString(raw: string): string {
  let cleaned = raw.trim();

  // Strip markdown code fences if present (```json ... ``` or ``` ...)
  const fenceRegex = /^```(?:json)?\s*([\s\S]*?)\s*```$/i;
  const matchFence = cleaned.match(fenceRegex);
  if (matchFence && matchFence[1]) {
    cleaned = matchFence[1].trim();
  } else {
    // If there's leading/trailing narrative around the first '{' and last '}'
    const firstBrace = cleaned.indexOf("{");
    const lastBrace = cleaned.lastIndexOf("}");
    if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
      cleaned = cleaned.substring(firstBrace, lastBrace + 1);
    }
  }

  // Remove single line comments // ...
  cleaned = cleaned.replace(/\/\/[^"\n\r]*/g, "");

  // Remove trailing commas in objects or arrays: e.g. { "a": 1, } -> { "a": 1 }
  cleaned = cleaned.replace(/,\s*([}\]])/g, "$1");

  return cleaned;
}

function normalizeMutation(item: unknown): unknown {
  if (!item || typeof item !== "object") return item;
  const mut = { ...(item as Record<string, unknown>) };

  // 1. Normalize action string
  const actionStr = String(mut.action || "").toUpperCase().trim().replace(/[- ]/g, "_");
  if (["ADD_NODE", "ADDNODE", "ADD_COMPONENT"].includes(actionStr)) {
    mut.action = "ADD_NODE";
  } else if (["REMOVE_NODE", "REMOVENODE", "DELETE_NODE"].includes(actionStr)) {
    mut.action = "REMOVE_NODE";
  } else if (["UPDATE_NODE", "UPDATENODE", "MODIFY_NODE"].includes(actionStr)) {
    mut.action = "UPDATE_NODE";
  } else if (["ADD_EDGE", "ADDEDGE", "CONNECT"].includes(actionStr)) {
    mut.action = "ADD_EDGE";
  } else if (["REMOVE_EDGE", "REMOVEEDGE", "DISCONNECT"].includes(actionStr)) {
    mut.action = "REMOVE_EDGE";
  }

  // 2. Sanitize ADD_NODE
  if (mut.action === "ADD_NODE" && mut.node && typeof mut.node === "object") {
    const node = { ...(mut.node as Record<string, unknown>) };
    if (!node.id || typeof node.id !== "string") {
      node.id = node.name
        ? String(node.name).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "")
        : `node-${Date.now().toString(36)}`;
    }
    if (!node.name || typeof node.name !== "string") {
      node.name = String(node.id);
    }

    // Normalize NodeType
    const typeStr = String(node.type || "service").toLowerCase().trim();
    if (["client", "frontend", "web", "ui", "mobile", "browser"].includes(typeStr)) {
      node.type = "client";
    } else if (["database", "db", "storage", "postgres", "mysql", "mongodb", "sql", "nosql"].includes(typeStr)) {
      node.type = "database";
    } else if (["cache", "redis", "memcached"].includes(typeStr)) {
      node.type = "cache";
    } else if (["queue", "bus", "broker", "kafka", "rabbitmq", "pubsub", "stream"].includes(typeStr)) {
      node.type = "queue";
    } else if (["gateway", "ingress", "proxy", "load_balancer", "traefik", "kong"].includes(typeStr)) {
      node.type = "gateway";
    } else if (["api", "endpoint", "rest", "graphql", "grpc", "llm"].includes(typeStr)) {
      node.type = "api";
    } else {
      node.type = "service";
    }

    if (node.responsibilities && !Array.isArray(node.responsibilities)) {
      node.responsibilities = [String(node.responsibilities)];
    }

    mut.node = node;
  }

  // 3. Sanitize ADD_EDGE
  if (mut.action === "ADD_EDGE" && mut.edge && typeof mut.edge === "object") {
    const edge = { ...(mut.edge as Record<string, unknown>) };
    if (edge.source && edge.target) {
      edge.source = String(edge.source);
      edge.target = String(edge.target);

      const relStr = String(edge.relationship || "connects_to").toLowerCase().trim().replace(/[- ]/g, "_");
      if (["reads_from", "reads", "queries", "fetches", "fetches_from"].includes(relStr)) {
        edge.relationship = "reads_from";
      } else if (["writes_to", "writes", "saves", "persists", "stores"].includes(relStr)) {
        edge.relationship = "writes_to";
      } else if (["publishes_to", "publishes", "produces", "emits"].includes(relStr)) {
        edge.relationship = "publishes_to";
      } else if (["subscribes_to", "subscribes", "consumes", "listens"].includes(relStr)) {
        edge.relationship = "subscribes_to";
      } else {
        edge.relationship = "connects_to";
      }

      mut.edge = edge;
    }
  }

  return mut;
}

/**
 * Parses and repairs an AI mutation plan from raw LLM output text.
 */
export function parseAndRepairMutationPlan(rawOutput: string): RepairResult {
  const warnings: string[] = [];

  if (!rawOutput || !rawOutput.trim()) {
    return {
      success: false,
      plan: null,
      recoveredMutationsCount: 0,
      droppedMutationsCount: 0,
      warnings: ["Empty AI output received"],
    };
  }

  const cleanedJson = sanitizeJsonString(rawOutput);

  let parsedRaw: unknown;
  try {
    parsedRaw = JSON.parse(cleanedJson);
  } catch (err) {
    // If still fails, try closing unclosed braces/brackets
    try {
      let patched = cleanedJson;
      const openBraces = (patched.match(/\{/g) || []).length;
      const closeBraces = (patched.match(/\}/g) || []).length;
      if (openBraces > closeBraces) {
        patched += "}".repeat(openBraces - closeBraces);
      }
      const openBrackets = (patched.match(/\[/g) || []).length;
      const closeBrackets = (patched.match(/\]/g) || []).length;
      if (openBrackets > closeBrackets) {
        patched += "]".repeat(openBrackets - closeBrackets);
      }
      parsedRaw = JSON.parse(patched);
      warnings.push("Auto-closed unbalanced brackets in LLM JSON payload");
    } catch {
      return {
        success: false,
        plan: null,
        recoveredMutationsCount: 0,
        droppedMutationsCount: 0,
        warnings: [`Failed to parse JSON: ${err instanceof Error ? err.message : String(err)}`],
      };
    }
  }

  // Handle case where root is directly an array of mutations
  if (Array.isArray(parsedRaw)) {
    parsedRaw = {
      explanation: "AI proposed architecture updates",
      mutations: parsedRaw,
    };
  }

  // Attempt strict validation first
  const strictResult = AIMutationPlanSchema.safeParse(parsedRaw);
  if (strictResult.success) {
    return {
      success: true,
      plan: strictResult.data,
      recoveredMutationsCount: strictResult.data.mutations.length,
      droppedMutationsCount: 0,
      warnings,
    };
  }

  // Fallback: If root is an object, salvage explanation and valid individual mutations
  if (typeof parsedRaw === "object" && parsedRaw !== null) {
    const candidate = parsedRaw as Record<string, unknown>;
    const explanation = typeof candidate.explanation === "string" 
      ? candidate.explanation 
      : "AI proposed architecture updates";

    const rawMutations = Array.isArray(candidate.mutations) 
      ? candidate.mutations 
      : Array.isArray(candidate.plan) 
      ? candidate.plan 
      : Array.isArray(candidate.changes) 
      ? candidate.changes 
      : [];
    const validMutations: GraphMutation[] = [];
    let dropped = 0;

    for (const item of rawMutations) {
      const normalized = normalizeMutation(item);
      const mutResult = GraphMutationSchema.safeParse(normalized);
      if (mutResult.success) {
        validMutations.push(mutResult.data);
      } else {
        dropped++;
        warnings.push(`Dropped malformed mutation: ${mutResult.error.issues.map((i) => i.message).join(", ")}`);
      }
    }

    if (validMutations.length > 0 || typeof candidate.explanation === "string") {
      return {
        success: true,
        plan: {
          explanation,
          mutations: validMutations,
        },
        recoveredMutationsCount: validMutations.length,
        droppedMutationsCount: dropped,
        warnings,
      };
    }
  }

  return {
    success: false,
    plan: null,
    recoveredMutationsCount: 0,
    droppedMutationsCount: 0,
    warnings: ["Output object does not contain a recoverable mutation plan"],
  };
}
